// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 reqID, bool repayDirect) internal {
        vm.assume(true);
        bool reverted;
        try c.clearRequest(reqID, repayDirect, true) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted);
    }

    function testFuzz_run(uint256 reqID, bool repayDirect) public {
        _run(reqID, repayDirect);
    }

    receive() external payable {}
}
